package com.wygtv.tv;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;import androidx.media3.common.MediaItem;import androidx.media3.exoplayer.ExoPlayer;import androidx.media3.ui.PlayerView;

public class MainActivity extends Activity {
 final int BG=0xff080F24, PANEL=0xff172B4D, BLUE=0xff4CB6FF; LinearLayout root,body,side,detail; TextView status; String mode="home", category="", name=""; JSONArray categories=new JSONArray(),items=new JSONArray(); int screenGeneration=0, listGeneration=0; Runnable playerReturn; ExoPlayer player; android.content.SharedPreferences prefs;
 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);} String saved(String k){return prefs.getString(k,"");}
 String accountPrefix(){return "account_"+android.util.Base64.encodeToString((saved("host")+"\n"+saved("user")).getBytes(java.nio.charset.StandardCharsets.UTF_8),android.util.Base64.NO_WRAP)+"_";}
 void migrateFavorites(){if(prefs.getBoolean("favorites_migrated",false))return;android.content.SharedPreferences.Editor edit=prefs.edit();for(Map.Entry<String,?> entry:prefs.getAll().entrySet())if(entry.getKey().startsWith("fav_")||entry.getKey().startsWith("ext_"))edit.putString(accountPrefix()+entry.getKey(),String.valueOf(entry.getValue()));edit.putBoolean("favorites_migrated",true).apply();}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("wygtv",MODE_PRIVATE);migrateFavorites();getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);home();}
 GradientDrawable bg(int color){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,0xff0A1934});g.setCornerRadius(dp(15));g.setStroke(dp(1),0xff42658B);return g;}
 TextView label(String t,int size){TextView v=new TextView(this);v.setText(t);v.setTextColor(-1);v.setTextSize(size);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 TextView button(String text,LinearLayout parent,Runnable r){TextView v=label(text,21);v.setFocusable(true);v.setPadding(dp(18),dp(13),dp(12),dp(13));v.setBackground(bg(PANEL));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(dp(5),dp(5),dp(5),dp(5));parent.addView(v,lp);v.setOnClickListener(w->r.run());v.setOnFocusChangeListener((w,f)->{v.setBackground(bg(f?0xff23639B:PANEL));v.setScaleX(f?1.025f:1f);v.setScaleY(f?1.025f:1f);});return v;}
 void shell(String title){screenGeneration++;listGeneration++;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(24),dp(14),dp(24),dp(12));root.setBackgroundColor(BG);setContentView(root);TextView h=label("✦ WygTV     "+title,30);h.setTypeface(null,Typeface.BOLD);h.setTextColor(BLUE);root.addView(h,new LinearLayout.LayoutParams(-1,dp(65)));body=new LinearLayout(this);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));status=label("",13);status.setTextColor(0xffA8C9E8);root.addView(status,new LinearLayout.LayoutParams(-1,dp(30)));updateStatus();}
 void updateStatus(){String s=saved("host");status.setText(s.isEmpty()?"No playlist connected":"Playlist: "+saved("title")+"  •  "+s+"  •  "+saved("expiry"));}
 void home(){
  mode="home";screenGeneration++;listGeneration++;
  FrameLayout scene=new FrameLayout(this);scene.addView(new BeowulfScene(this),new FrameLayout.LayoutParams(-1,-1));setContentView(scene);
  LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(dp(36),dp(20),dp(36),dp(18));scene.addView(layout,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);layout.addView(header,new LinearLayout.LayoutParams(-1,dp(52)));
  TextView brand=label("WygTV",32);brand.setTypeface(null,Typeface.BOLD);brand.setTextColor(0xffEACB86);header.addView(brand,new LinearLayout.LayoutParams(0,-1,1));
  LinearLayout center=new LinearLayout(this);center.setOrientation(LinearLayout.VERTICAL);center.setGravity(Gravity.CENTER);layout.addView(center,new LinearLayout.LayoutParams(-1,0,1));
  TextView welcome=label("YOUR NEXT SAGA AWAITS",15);welcome.setTextColor(0xffEACB86);welcome.setLetterSpacing(.18f);welcome.setGravity(Gravity.CENTER);center.addView(welcome,new LinearLayout.LayoutParams(-1,dp(35)));
  TextView heading=label("Choose your adventure",30);heading.setTypeface(null,Typeface.BOLD);heading.setGravity(Gravity.CENTER);center.addView(heading,new LinearLayout.LayoutParams(-1,dp(60)));
  LinearLayout tiles=new LinearLayout(this);tiles.setGravity(Gravity.CENTER);center.addView(tiles,new LinearLayout.LayoutParams(-1,dp(135)));
  TextView live=homeTile("▣","Live TV",tiles,()->browse("live"));homeTile("▶","Movies",tiles,()->browse("vod"));homeTile("▤","Series",tiles,()->browse("series"));homeTile("★","Favorites",tiles,()->favorites());
  LinearLayout footer=new LinearLayout(this);footer.setGravity(Gravity.CENTER_VERTICAL);layout.addView(footer,new LinearLayout.LayoutParams(-1,dp(56)));
  TextView manage=button("Manage Playlist",footer,()->login());manage.setTextSize(16);manage.setGravity(Gravity.CENTER);manage.setLayoutParams(new LinearLayout.LayoutParams(dp(190),dp(48)));
  status=label("",13);status.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);status.setTextColor(0xffB4C0D1);footer.addView(status,new LinearLayout.LayoutParams(0,-1,1));status.setText(saved("host").isEmpty()?"Connect your playlist to begin":"Connected • "+saved("title"));
  manage.setId(View.generateViewId());live.setId(View.generateViewId());for(int i=0;i<tiles.getChildCount();i++)tiles.getChildAt(i).setNextFocusDownId(manage.getId());manage.setNextFocusUpId(live.getId());live.requestFocus();
 }
 TextView homeTile(String icon,String title,LinearLayout parent,Runnable action){
  TextView tile=label(icon+"\n"+title,24);tile.setGravity(Gravity.CENTER);tile.setTypeface(null,Typeface.BOLD);tile.setFocusable(true);tile.setClickable(true);tile.setBackground(homeTileBackground(false));
  LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);lp.setMargins(dp(8),dp(10),dp(8),dp(10));parent.addView(tile,lp);tile.setOnClickListener(v->action.run());
  tile.setOnFocusChangeListener((v,focused)->{tile.setBackground(homeTileBackground(focused));tile.setTextColor(focused?0xff101B2C:0xffF5E8CA);tile.animate().scaleX(focused?1.035f:1f).scaleY(focused?1.035f:1f).setDuration(130).start();});return tile;
 }
 GradientDrawable homeTileBackground(boolean focused){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,focused?new int[]{0xffF0D797,0xffBA904A}:new int[]{0xe618293E,0xec0B1525});g.setCornerRadius(dp(12));g.setStroke(dp(focused?3:1),focused?0xffFFF0C1:0xff75684C);return g;}

 void login(){mode="login";shell("MANAGE PLAYLISTS");ScrollView scroll=new ScrollView(this);body.addView(scroll);LinearLayout form=new LinearLayout(this);form.setPadding(dp(100),dp(10),dp(100),0);form.setOrientation(LinearLayout.VERTICAL);scroll.addView(form);EditText title=field(form,"Playlist name",saved("title"));EditText host=field(form,"Server URL (http://host:port)",saved("host"));EditText user=field(form,"Username",saved("user"));EditText pass=field(form,"Password",saved("pass"));pass.setInputType(129);button("Save & Connect",form,()->{String h=host.getText().toString().trim().replaceAll("/+$","");String u=user.getText().toString(),pw=pass.getText().toString();
if(!XtreamProtocol.validLogin(h,u,pw)){new AlertDialog.Builder(this).setMessage("Enter an HTTP or HTTPS server URL, username and password.").setPositiveButton("OK",null).show();return;}
String loginUrl=h+"/player_api.php?username="+enc(u)+"&password="+enc(pw);
fetch(loginUrl,data->{JSONObject info=data.optJSONObject("user_info");if(info==null||info.optInt("auth",0)!=1||!"Active".equalsIgnoreCase(info.optString("status"))){new AlertDialog.Builder(this).setMessage("Login rejected or account inactive. Your saved playlist was not changed.").setPositiveButton("OK",null).show();return;}
prefs.edit().putString("title",title.getText().toString()).putString("host",h).putString("user",u).putString("pass",pw).putString("expiry",info.optString("exp_date","Unknown")).apply();home();},"Connection failed");});button("Return to Home",form,()->home());}
 EditText field(LinearLayout parent,String hint,String val){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setText(val);e.setTextColor(-1);e.setHintTextColor(0xffAABBD2);parent.addView(e,new LinearLayout.LayoutParams(-1,dp(57)));return e;}
 String base(){return saved("host")+"/player_api.php?username="+enc(saved("user"))+"&password="+enc(saved("pass"));}String enc(String s){return XtreamProtocol.encode(s);}

 interface Done{void run(JSONObject obj);} void request(String action,Done cb,String error){if(saved("host").isEmpty()){new AlertDialog.Builder(this).setMessage("Add a playlist first").setPositiveButton("Login",(d,w)->login()).setNegativeButton("Cancel",null).show();return;}fetch(action.equals("player_api.php")?base():base()+"&action="+action,cb,error);}
 void fetch(String url,Done cb,String error){final int generation=screenGeneration;new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(16000);try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);String text=out.toString("UTF-8");JSONObject obj=text.trim().startsWith("[")?new JSONObject().put("list",new JSONArray(text)):new JSONObject(text);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)cb.run(obj);});}finally{c.disconnect();}}catch(Exception e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)new AlertDialog.Builder(this).setMessage(error+". Check the server address, account and network, then retry.").setPositiveButton("OK",null).show();});}}).start();}
 void browse(String m){mode=m;category="";shell(m.equals("live")?"LIVE TV":m.equals("vod")?"MOVIES":"SERIES");side=new LinearLayout(this);side.setOrientation(LinearLayout.VERTICAL);ScrollView categoryScroll=new ScrollView(this);categoryScroll.setFillViewport(true);categoryScroll.addView(side);body.addView(categoryScroll,new LinearLayout.LayoutParams(0,-1,1));detail=new LinearLayout(this);detail.setOrientation(LinearLayout.VERTICAL);body.addView(detail,new LinearLayout.LayoutParams(0,-1,2));button("← Home",side,()->home());button("★ Favorites",side,()->favorites());request(m.equals("live")?"get_live_categories":m.equals("vod")?"get_vod_categories":"get_series_categories",o->{categories=o.optJSONArray("list");if(categories==null)categories=new JSONArray();showCategories();},"Unable to load categories");}
 void showCategories(){side.removeViews(2,Math.max(0,side.getChildCount()-2));button("All categories",side,()->loadItems(""));for(int i=0;i<categories.length();i++){JSONObject c=categories.optJSONObject(i);if(c==null)continue;String id=c.optString("category_id"),title=c.optString("category_name","Category");button("› "+title,side,()->loadItems(id));}loadItems("");}
 void loadItems(String id){final int ticket=++listGeneration;category=id;String a=mode.equals("live")?"get_live_streams":mode.equals("vod")?"get_vod_streams":"get_series";request(a+(id.isEmpty()?"":"&category_id="+enc(id)),o->{if(ticket!=listGeneration)return;items=o.optJSONArray("list");if(items==null)items=new JSONArray();showItems();},"Unable to load content");}
 void showItems(){showItems(0);}
 void showItems(int offset){detail.removeAllViews();button("← Categories",detail,()->{if(side.getChildCount()>2)side.getChildAt(2).requestFocus();});ScrollView sv=new ScrollView(this);detail.addView(sv);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);sv.addView(list);int limit=Math.min(items.length(),offset+100);if(offset>0)button("← Previous page",list,()->showItems(Math.max(0,offset-100)));for(int i=offset;i<limit;i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String title=item.optString("name","Untitled");button(title,list,()->select(item));}if(limit<items.length())button("Next page →",list,()->showItems(limit));if(list.getChildCount()>0)list.getChildAt(0).requestFocus();}
 void select(JSONObject item){String title=item.optString("name","Untitled");String type=mode;String id=item.optString(type.equals("series")?"series_id":"stream_id");new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"Play / Open",isFavorite(type,id)?"Remove Favorite":"Add Favorite",type.equals("live")?"Program guide":"Close"},(d,which)->{if(which==0){if(type.equals("series"))episodes(id,title);else play(type,id,item.optString("container_extension",type.equals("live")?"ts":"mp4"),title);}if(which==2&&type.equals("live"))guide(id,title);if(which==1){String key=accountPrefix()+"fav_"+type+"_"+id;boolean remove=isFavorite(type,id);prefs.edit().putString(key,remove?"":title).putString(accountPrefix()+"ext_"+type+"_"+id,remove?"":item.optString("container_extension",type.equals("live")?"ts":"mp4")).apply();}}).show();}
 boolean isFavorite(String type,String id){return !saved(accountPrefix()+"fav_"+type+"_"+id).isEmpty();}
 void favorites(){mode="favorites";shell("FAVORITES");LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView favoritesScroll=new ScrollView(this);favoritesScroll.addView(list);body.addView(favoritesScroll,new LinearLayout.LayoutParams(-1,-1));button("← Home",list,()->home());for(Map.Entry<String,?> e:prefs.getAll().entrySet()){String k=e.getKey();if(!k.startsWith(accountPrefix()+"fav_")||String.valueOf(e.getValue()).isEmpty())continue;String[] parts=k.substring(accountPrefix().length()).split("_",3);if(parts.length!=3)continue;String t=parts[1],id=parts[2],title=String.valueOf(e.getValue());button("★ "+title,list,()->{if(t.equals("series"))episodes(id,title);else new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"Play","Remove Favorite"},(dialog,choice)->{if(choice==0)play(t,id,saved(accountPrefix()+"ext_"+t+"_"+id).isEmpty()?(t.equals("live")?"ts":"mp4"):saved(accountPrefix()+"ext_"+t+"_"+id),title);else{prefs.edit().remove(k).remove(accountPrefix()+"ext_"+t+"_"+id).apply();favorites();}}).show();});}}
 void episodes(String id,String title){playerReturn=()->episodes(id,title);mode="episodes";shell("SERIES • "+title);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView sv=new ScrollView(this);body.addView(sv);sv.addView(list);button("← Series",list,()->browse("series"));request("get_series_info&series_id="+enc(id),o->{JSONObject seasons=o.optJSONObject("episodes");if(seasons==null)return;Iterator<String> keys=seasons.keys();while(keys.hasNext()){String season=keys.next();button("Season "+season,list,()->{JSONArray ep=seasons.optJSONArray(season);if(ep==null)return;list.removeViews(1,list.getChildCount()-1);button("← Seasons",list,()->episodes(id,title));for(int i=0;i<ep.length();i++){JSONObject e=ep.optJSONObject(i);if(e==null)continue;String eid=e.optString("id"),ext=e.optString("container_extension","mp4"),et=e.optString("title","Episode "+(i+1));button(et,list,()->play("series",eid,ext,et));}});}},"Unable to load episodes");}
 String epgText(String value){try{return new String(android.util.Base64.decode(value,android.util.Base64.DEFAULT),java.nio.charset.StandardCharsets.UTF_8);}catch(IllegalArgumentException ex){return value;}}
 void guide(String id,String title){request("get_short_epg&stream_id="+enc(id)+"&limit=20",o->{JSONArray entries=o.optJSONArray("epg_listings");StringBuilder text=new StringBuilder();if(entries!=null)for(int i=0;i<entries.length();i++){JSONObject e=entries.optJSONObject(i);if(e==null)continue;text.append(e.optString("start")).append(" – ").append(e.optString("end")).append("\n").append(epgText(e.optString("title"))).append("\n").append(epgText(e.optString("description"))).append("\n\n");}new AlertDialog.Builder(this).setTitle(title+" • Program guide").setMessage(text.length()==0?"No guide data available from this provider.":text.toString()).setPositiveButton("Close",null).show();},"Unable to load guide");}
 void play(String type,String id,String ext,String title){String previousMode=mode;Runnable returnScreen=playerReturn;playerReturn=previousMode.equals("episodes")?returnScreen:previousMode.equals("favorites")?()->favorites():()->{browse(previousMode);};String path=type.equals("live")?"live":type.equals("vod")?"movie":"series";String url=saved("host")+"/"+path+"/"+enc(saved("user"))+"/"+enc(saved("pass"))+"/"+id+"."+ext;screenGeneration++;mode="player";if(player!=null)player.release();player=new ExoPlayer.Builder(this).build();PlayerView view=new PlayerView(this);view.setPlayer(player);view.setUseController(true);setContentView(view);player.setMediaItem(MediaItem.fromUri(url));player.prepare();player.play();view.requestFocus();}
 @Override public void onBackPressed(){if(player!=null){player.release();player=null;if(playerReturn!=null)playerReturn.run();else home();return;}if(mode.equals("home")){super.onBackPressed();return;}home();}
 @Override protected void onStop(){if(player!=null)player.pause();super.onStop();}
 @Override protected void onDestroy(){if(player!=null){player.release();player=null;}super.onDestroy();}
}

